sys_script.script:
(function executeRule(current, previous /*null when async*/ ) {
    //MSSRBXSN-1814:After-Insert BR to update Expected Processing date and template_identification as 'EMPTY BASKET ID' in Parent Chat record with empty Basket ID field value
    var dateTime = new GlideDateTime();
    if (current.basket_id == "") {
        current.template_identification = 'EMPTY BASKET ID';
    }
    if (current.stock_connect_trade == 'Yes') {//if Stock connect trade = Yes on Parent chat record
        dateTime.addSeconds(300); //add5minutes
        current.expected_processing_date = dateTime.getDisplayValue();
    } else {//if Stock connect trade = No on Parent chat record
        dateTime.addSeconds(900); //add15minutes
        current.expected_processing_date = dateTime.getDisplayValue();
    }
    current.setWorkflow(false);
    current.update();
    current.setWorkflow(true);
})(current, previous);
